GimCorpus.put(468,0,[[2,1,"וכן העד השני וכו' עד הרי עדותן בטלה. א\"א טעה בזה כי הבדיקות אם אמר איני יודע אין עדותן בטלה:",1,0],[3,9,"אמרו על תנאי וכו'. א\"א לדעת רבו הוא זה אבל הגאון ז\"ל לא אמר כן אלא נאמנין בכל ענין וכן עיקר:",1,0],[6,3,"וכן מקיימין את השטר וכו'. א\"א אין הגירסא שלו כגירסא שלנו עכ\"ל:",1,0],[8,4,"הואיל והדבר כן שטר שיצא לבית דין ובאו עדים וכו' עד וכל מי שאינו דן כזה לא ידעבדיני ממונות בין ימינו לשמאלו. א\"א ויש מי שאין מורין כן ויודעין בדינין כמותו שאם אמרו אין לנו זכרון כלל אין זו סתירה ויותר מזה שאפילו אמרו כתב ידינו הוא אבל מעולם לא היתה מלוה כי אם אמנה היתה אינן נאמנין אבל אם אמרו דומה חתימה זו לכתב ידינו אבל מזוייפת היא כי מעולם לא חתמנו בשטר זה ודאי יכולין לפוסלו:",1,0],[8,5,"אחד הכותב עדותו על השטר. א\"א זה אינו:",1,0],[8,5,"או שנמצא אצלו כתוב בפנקסו ובכתב ידו וכו' עד אלא מפי האחר שמע והעיד. א\"א אפשר לקיימו כגון שהיה השטר תחת יד העדים ואמר הלוה אל תתנו לו את השטר עד שיתן לי המעות ונסתפק האחד אם הודה הלוה בפניהם שקבל אם לאו כשיראה השטר יזכור מתוך ראיה שנצטוה לתתו למלוה או שיזכירהו העד ואין הדעת נוחה בכל זה:",2,0],[11,8,"לפיכך החשוד על דבר וכו' עד ואין אימת (הפסד) ממון עליהם. א\"א זה אינו כן ומשנה שלמה היא במסכת דמאי פ\"ד הלוקח פירות ממי שאינו נאמן על המעשרות ושכח לעשרן שואל לו בשבת ואוכל על פיו חשכה מוצ\"ש לא יאכל עד שיעשר ואי קשיא לך פסקא אחריתי הנכנס לעיר ואינו מכיר שם אדם נאמן ואמר לו אחד אני איני נאמן איש פלוני נאמן ה\"ז נאמן הא אמרינן בירושלמי אכסנאי שאני ועוד משנה שלימה החשוד בדבר לא דנו ולא מעידו ומומי בכור שאני דקנסא בעלמא הוא ומש\"ה נאמן הוא על חבירו:",1,0],[12,2,"וכן כל כיוצא בזה וכו' עד שאין אדם קרוב אצל ממונו. א\"א מן המפרשים הטובים יש שמפרשים פלוני רבע את שורי שגם הרובע אינו נהרג לפי שהעדות נגעה על שורו דלא פלגינן דיבורא וגם על שורו נתכוון להעיד וכשם שאינו נאמן על שורו כך אינו נאמן על הרובע דעדות שבטלה מקצתה בטלה כולה:",1,0],[15,6,"וכן לוקח ראשון מעיד ללוקח שני וכו' עד והרי יש לו שדה אחרת שיגבה. א\"א דוקא בשעשאה אפותיקי עכ\"ל:",1,0],[20,2,"נהרג זה שהעידו עליו וכו'. א\"א שבוש הוא זה:",1,0],[20,3,"אבל אם היה הפסק וכו' עד נפסלה כולה. א\"א איני יודע מהו כי מאחר שלא באו תוך כדי דבור ונחשבו שתי כתות לענין הזמה למה תבטל עדות הכת האחרונה ויהרג הרוצח ועוד מה זה שאמר והשנים האחרים וכו' אין נענשין ומה עונש ראוי להם:",1,0],[20,4,"ואין לעדים זוממין שגגה וכו'. א\"א זה הטעם לא ידעתי מהו ואם מפני שאמר הכתוב תורה אחת יהיה לכם לעושה בשגגה א\"כ מגדף לדעת חכמים לא יהא צריך התראה:",1,0],[21,4,"העידו על פלוני שהפיל שן עבדו וכו'. א\"א והוא כתב בהלכות חובל שהאדון אינו משלם אלא אם תפס העבד ואם כן העדים שהוזמו למה משלמין:",1,0],[22,2,"יראה לי ששבועה זו שישבע על השאר וכו' עד ולא תהא הודאת פיו גדולה מהעדאת עדים כמו שבארנו. א\"א יש מקשין על זה והלא שטר שעבוד קרקעות הוא ועוד אני אומר שאין זה דומה לדרבי חייא דהתם טענה אחת ועדות העדים במקצת כהודאה דמיא אבל הכא שני שטרות שתי טענות הן וכל שכן שהן שתי כתי עדים ועוד כי הוא עצמו כתב בטוען את חבירו חמשים בשטר וחמשים בלא שטר והודה בשטר וכפר השאר פטור:",1,0]]);
